http:request.http:query-params:
#[%dw 2.0
output application/java
---
{
	materialNumber : (vars.params.productId as Number) as String default ""
	
	}]

ee:variables.ee:set-variable:
%dw 2.0
output application/json
var errorBody = payload
---
{
    "error": {
        "code": (errorBody."status-code" default vars.statusCode) as String,
        "status": (errorBody.status default "ERROR"),
        "message": (errorBody.description default ""),
    }
}

%dw 2.0
output application/json
ns S http://schemas.xmlsoap.org/soap/envelope/
---
do {
    var returnRec = entriesOf(payload.body.S#Envelope.S#Body)[0].value.return
    ---
    {
        "error": {
            "code": "404",
            "status": "NOT_FOUND",
            "message": (returnRec.statusMessage as String default "Product not found in Windchill"),
            "correlationId": vars.correlationId default "",
            "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
        }
    }
}

%dw 2.0
output application/json
---
{
    "error": {
        "code": "SERVICE_UNAVAILABLE",
        "status": "SERVICE_UNAVAILABLE",
        "message": "Windchill system is currently unavailable. Please try again later.",
        "correlationId": vars.correlationId default "",
        "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
    }
}

%dw 2.0
output application/json
---
{
    "error": {
        "code": "SECURITY_ERROR",
        "status": "INTERNAL_SERVER_ERROR",
        "message": "Windchill authentication or security failure. Please contact support.",
        "correlationId": vars.correlationId default "",
        "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
    }
}

